<template>
  <main class="profile-page">
    <section class="wrap">
      <header class="hero"><div><span>MEMBER ACCOUNT</span><h1>My Profile</h1><p>Your StockWell account, Stokvel membership, shared wallet and recent orders.</p></div><div class="avatar">{{ initials }}</div></header>
      <div v-if="loading" class="state">Loading your profile…</div>
      <div v-else-if="error" class="state error">{{ error }}</div>
      <template v-else>
        <section class="stats"><article><span>CONTRIBUTIONS</span><strong>R {{ money(stats.paid_total) }}</strong><small>{{ stats.contribution_count }} recorded</small></article><article><span>WALLET</span><strong>R {{ money(dashboard.wallet?.available_balance) }}</strong><small>Available to the group</small></article><article><span>ORDERS</span><strong>{{ stats.order_count }}</strong><small>R {{ money(stats.order_total) }} total</small></article></section>
        <section class="grid"><article class="panel"><span class="label">MEMBER</span><h2>{{ profile.full_name }}</h2><div class="details"><div><span>Email</span><strong>{{ profile.email }}</strong></div><div><span>Phone</span><strong>{{ profile.phone_number || 'Not provided' }}</strong></div><div><span>Account role</span><strong>{{ profile.role }}</strong></div><div><span>Stokvel role</span><strong>{{ role }}</strong></div><div><span>Member since</span><strong>{{ formatDate(profile.created_at) }}</strong></div></div></article><article class="panel"><span class="label">STOKVEL</span><h2>{{ dashboard.stokvel?.stokvel_name || 'Your Stokvel' }}</h2><p>{{ dashboard.stokvel?.description || 'Your shared StockWell community.' }}</p><div class="wallet-box"><span>GROUP WALLET</span><strong>R {{ money(dashboard.wallet?.available_balance) }}</strong><small>R {{ money(dashboard.wallet?.paid_contributions) }} contributed · R {{ money(dashboard.wallet?.spent_amount) }} spent</small></div><RouterLink class="button" to="/member-dashboard">Open Group Hub →</RouterLink></article></section>
        <section v-if="dashboard.members?.length" class="panel"><div class="heading"><div><span class="label">GROUP MEMBERS</span><h2>Members</h2></div><span>{{ dashboard.members.length }}</span></div><div class="members"><div v-for="member in dashboard.members" :key="member.user_id"><b>{{ member.full_name }}</b><small>{{ member.email }}</small><span>{{ member.role }}</span></div></div></section>
        <section class="panel contribution"><div><span class="label">GROUP FUNDING</span><h2>Contribute through PayFast</h2><p>StockWell does not store your card details. Your wallet updates after PayFast confirms the payment.</p></div><div class="contribute-form"><input v-model.number="amount" type="number" min="1" step="0.01" placeholder="Amount (R)"><button :disabled="starting || !amount" @click="contribute">{{ starting ? 'Opening PayFast…' : 'Continue to PayFast' }}</button></div><p v-if="paymentError" class="error">{{ paymentError }}</p></section>
        <section class="panel"><div class="heading"><div><span class="label">RECENT ORDERS</span><h2>Order history</h2></div><RouterLink class="text" to="/order-history">View all →</RouterLink></div><div v-if="orders.length" class="orders"><div v-for="order in orders" :key="order.order_id"><b>#{{ order.order_id }}</b><span>{{ formatDate(order.order_date) }}</span><strong>R {{ money(order.total_amount) }}</strong><em>{{ order.order_status }}</em></div></div><p v-else>No orders have been placed yet.</p></section>
      </template>
    </section>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import { getMemberDashboard, getPaymentOptions, createPayfastCheckout, getOrderHistory } from '../services/api.js';
import api from '../services/api.js';

const loading=ref(true),error=ref(''),profile=ref({}),dashboard=ref({}),orders=ref([]),amount=ref(null),starting=ref(false),paymentError=ref(''),stats=ref({paid_total:0,contribution_count:0,order_count:0,order_total:0});
const initials=computed(()=>String(profile.value.full_name||'Member').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase());
const role=computed(()=>String(dashboard.value.membership?.stokvel_role||'MEMBER').toUpperCase());
const money=v=>Number(v||0).toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2});
const formatDate=v=>v?new Date(v).toLocaleDateString('en-ZA',{day:'2-digit',month:'short',year:'numeric'}):'—';
async function load(){loading.value=true;error.value='';try{const [profileResponse,dashboardResponse,paymentResponse,historyResponse]=await Promise.all([api.get('/api/users/profile'),getMemberDashboard(),getPaymentOptions(),getOrderHistory()]);profile.value=profileResponse.data?.user||{};dashboard.value={...dashboardResponse,wallet:paymentResponse.wallet};orders.value=Array.isArray(historyResponse.orders)?historyResponse.orders.slice(0,6):[];stats.value={paid_total:Number(dashboardResponse.wallet?.paid_contributions||0),contribution_count:Array.isArray(dashboardResponse.contributions)?dashboardResponse.contributions.length:0,order_count:Array.isArray(historyResponse.orders)?historyResponse.orders.length:0,order_total:(historyResponse.orders||[]).reduce((sum,o)=>sum+Number(o.total_amount||0),0)};}catch(e){console.error(e);error.value=e.response?.data?.message||'Unable to load your profile.'}finally{loading.value=false}}
async function contribute(){if(starting.value||!amount.value)return;starting.value=true;paymentError.value='';try{const checkout=await createPayfastCheckout({amount:Number(amount.value)});const form=document.createElement('form');form.method='POST';form.action=checkout.action;form.style.display='none';Object.entries(checkout.fields||{}).forEach(([name,value])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input)});document.body.appendChild(form);form.submit()}catch(e){paymentError.value=e.response?.data?.message||'Unable to start the PayFast payment.';starting.value=false}}
onMounted(load);
</script>

<style scoped>
.profile-page{min-height:100vh;background:var(--sw-page-background);color:var(--sw-page-text);padding:40px 20px 80px}.wrap{max-width:1120px;margin:auto}.hero,.panel,.stats article{background:var(--sw-page-surface);border:1px solid var(--sw-input-border);border-radius:22px;box-shadow:var(--sw-card-shadow,0 12px 30px rgba(0,0,0,.07))}.hero{padding:34px;display:flex;justify-content:space-between;gap:20px;align-items:center;background:var(--sw-page-gradient)}.hero>div>span,.label{font:800 10px var(--sw-font-body);letter-spacing:.14em;color:var(--sw-gold-500)}h1{font:800 clamp(42px,7vw,68px)/.95 var(--sw-font-heading);margin:14px 0 10px}h2{margin:8px 0 12px}.hero p,.panel p,.panel small{color:var(--sw-page-text-soft);line-height:1.6}.avatar{width:78px;height:78px;border-radius:50%;display:grid;place-items:center;background:var(--sw-gold-500);color:var(--sw-purple-900);font-weight:900}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0}.stats article{padding:20px}.stats span,.stats small{display:block;color:var(--sw-page-text-soft);font-size:10px}.stats strong{display:block;font:800 27px var(--sw-font-heading);margin:10px 0 4px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{padding:24px;margin-bottom:18px}.details{display:grid;gap:0}.details div{display:flex;justify-content:space-between;gap:15px;padding:13px 0;border-bottom:1px solid var(--sw-input-border)}.details span{color:var(--sw-page-text-soft)}.details strong{text-align:right}.wallet-box{display:grid;gap:6px;margin:20px 0;padding:17px;border:1px solid var(--sw-input-border);border-radius:15px;background:var(--sw-page-background)}.wallet-box span{font-size:9px;color:var(--sw-page-text-soft)}.wallet-box strong{font:800 25px var(--sw-font-heading);color:var(--sw-gold-500)}.button,.text{color:var(--sw-purple-700);font-weight:800;text-decoration:none}.button{display:inline-block;padding:11px 15px;border-radius:10px;background:var(--sw-gold-500);color:var(--sw-purple-900)}.heading{display:flex;justify-content:space-between;align-items:center;gap:15px}.members{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.members>div{display:grid;gap:3px;padding:13px;border:1px solid var(--sw-input-border);border-radius:13px}.members span{font-size:9px;color:var(--sw-gold-500)}.contribution{display:flex;justify-content:space-between;gap:25px;align-items:end}.contribute-form{display:flex;gap:8px;min-width:330px}.contribute-form input{flex:1;padding:12px;border:1px solid var(--sw-input-border);border-radius:10px;background:var(--sw-page-background);color:var(--sw-page-text)}.contribute-form button{padding:12px 16px;border:0;border-radius:10px;background:var(--sw-gold-500);color:var(--sw-purple-900);font-weight:800}.contribute-form button:disabled{opacity:.5}.orders{display:grid}.orders>div{display:grid;grid-template-columns:70px 1fr auto auto;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid var(--sw-input-border)}.orders em{font-style:normal;font-size:10px;padding:5px 8px;border-radius:999px;background:rgba(121,93,137,.1)}.state{text-align:center;padding:60px}.error{color:#b42318}@media(max-width:750px){.hero,.contribution{flex-direction:column;align-items:flex-start}.stats,.grid{grid-template-columns:1fr}.members{grid-template-columns:1fr}.contribute-form{width:100%;min-width:0}.orders>div{grid-template-columns:1fr auto}.orders em{justify-self:start}}
</style>
